<?php
// views/user/laporan/laporanbulanan.php - FINAL GABUNG UKS.CSS
batasi_akses_role(['admin','petugas']);
$bulan=$_GET['bulan']??date('m'); $tahun=$_GET['tahun']??date('Y');
$q=mysqli_query($koneksi,"SELECT p.*, s.namasiswa, g.namaguru, u.namauser, GROUP_CONCAT(CONCAT(b.namabarang,' x',dp.jumlahkeluar) SEPARATOR ', ') as obat FROM penanganan p LEFT JOIN siswa s ON p.idsiswa=s.idsiswa LEFT JOIN guru g ON p.idguru=g.idguru LEFT JOIN user u ON p.iduser=u.iduser LEFT JOIN detailpenanganan dp ON p.idpenanganan=dp.idpenanganan LEFT JOIN barang b ON dp.idbarang=b.idbarang WHERE MONTH(p.tanggalpenanganan)='$bulan' AND YEAR(p.tanggalpenanganan)='$tahun' GROUP BY p.idpenanganan ORDER BY p.tanggalpenanganan DESC");
?>
<div class="dash">
  <div class="content-header"><div class="container-fluid"><div class="row mb-2 align-items-center">
    <div class="col-sm-6"><h1 class="m-0 font-weight-bold" style="color:var(--dark)"><i class="fas fa-calendar-alt mr-2" style="color:var(--teal)"></i> Laporan Bulanan</h1><small class="text-muted">UKS Digital - <b style="color:var(--teal)">Rekap Bulanan</b> | <span class="badge-mint"><?= date('F Y',mktime(0,0,0,$bulan,1,$tahun)) ?></span></small></div>
    <div class="col-sm-6 text-right"><form method="GET" class="form-inline float-right"><input type="hidden" name="halaman" value="laporanbulanan"><select name="bulan" class="form-control form-control-sm mr-1"><?php for($b=1;$b<=12;$b++){ $bl=str_pad($b,2,'0',STR_PAD_LEFT); echo "<option value='$bl' ".($bulan==$bl?'selected':'').">".date('F',mktime(0,0,0,$b,1))."</option>"; } ?></select><select name="tahun" class="form-control form-control-sm mr-2"><?php for($t=date('Y');$t>=2023;$t--) echo "<option value='$t' ".($tahun==$t?'selected':'').">$t</option>"; ?></select><button class="btn-toska" style="padding:6px 16px; font-size:12px">Tampilkan</button> <a href="index.php?halaman=cetaklaporanbulanan&bulan=<?= $bulan ?>&tahun=<?= $tahun ?>" target="_blank" class="btn-cetak ml-1"><i class="fas fa-print mr-1"></i> Cetak</a></form></div>
  </div></div></div>
  <div class="content"><div class="container-fluid"><div class="uk-card-lap">
    <div class="header-lap"><h6 class="font-weight-bold mb-0" style="color:var(--dark)"><i class="fas fa-calendar-alt mr-2" style="color:var(--teal)"></i> Bulan <?= date('F Y',mktime(0,0,0,$bulan,1,$tahun)) ?></h6><span class="badge-mint"><?= mysqli_num_rows($q) ?> Pasien</span></div>
    <div class="table-responsive"><table class="table table-hover table-lap"><thead><tr><th>No</th><th>Tanggal</th><th>Pasien</th><th>Keluhan</th><th>Status</th><th>Obat</th></tr></thead><tbody><?php $no=1; while($r=mysqli_fetch_assoc($q)): ?><tr><td class="text-center font-weight-bold text-muted"><?= $no++ ?></td><td><?= date('d/m/Y',strtotime($r['tanggalpenanganan'])) ?></td><td><b style="color:var(--dark)"><?= $r['namasiswa']?:$r['namaguru'] ?></b></td><td><?= htmlspecialchars($r['keluhan']) ?></td><td><span class="badge-<?= $r['statuspasien']=='sembuh'?'sembuh':($r['statuspasien']=='rujuk'?'rujuk':'istirahat') ?>"><?= $r['statuspasien'] ?></span></td><td><small><?= $r['obat']?:'-' ?></small></td></tr><?php endwhile; ?></tbody></table></div>
  </div></div></div>
</div>